const HASH_SEGREDO = "7ee64e43f403e0f523a65fcffe619a7bb9c3cd402574f694e9093be55e383af5";
const SESSAO = "cin";
const NUMERO_PROPRIO = "553584215361";
// Why Code: confere o segredo e separa, num passo so, mensagem de alguem, mensagem
// digitada no celular do proprio numero (pausa o robo) e evento da sessao do WhatsApp;
// normaliza o comando (SAIR/VOLTAR).
// Constantes (montar-entrada.mjs): HASH_SEGREDO, SESSAO, NUMERO_PROPRIO
const entrada = $('Hash do segredo').first().json;
const corpo = entrada.body || {};
const p = corpo.payload || {};
const autorizado = entrada.segredoHash === HASH_SEGREDO;
const evento = String(corpo.event || '');
const daSessao = corpo.session === SESSAO;

if (evento === 'session.status') {
  return [{ json: { valido: autorizado && daSessao, autorizado, tipoEvento: 'sessao', status: String(p.status || ''), chatId: '', ehLid: false, comando: 'sessao' } }];
}

const deMim = p.fromMe === true;
const origem = String(p.source || '');
// O WAHA poe o chat em "from" tambem nas mensagens do proprio numero. Se vier o
// proprio numero ali, o chat esta em "to".
let chat = String(p.from || '');
const proprio = String((corpo.me && corpo.me.id) || NUMERO_PROPRIO).split('@')[0].split(':')[0];
if (deMim && p.to && (!chat || chat.split('@')[0].split(':')[0] === proprio)) chat = String(p.to);
const ehChat = /@(c\.us|lid|s\.whatsapp\.net)$/.test(chat);
const ehMensagem = evento === 'message' || evento === 'message.any';
// Do proprio numero, so a mensagem digitada no celular (source "app") conta: ela
// pausa o robo naquela conversa. A que saiu pela API (avisos e respostas) e ignorada.
const valido = autorizado && ehMensagem && daSessao && ehChat && (!deMim || origem === 'app');
const normal = String(p.body || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toUpperCase().replace(/[^A-Z]+/g, ' ').trim();
let comando = 'outro';
if (deMim) comando = 'pausar';
else if (['SAIR', 'PARAR', 'PARE', 'STOP'].includes(normal)) comando = 'sair';
else if (['VOLTAR', 'VOLTA'].includes(normal)) comando = 'voltar';
return [{ json: { valido, autorizado, tipoEvento: 'mensagem', chatId: chat, ehLid: chat.endsWith('@lid'), comando } }];

// Why Code: registra a mudanca de estado da sessao do WhatsApp (WAHA, evento
// session.status) e decide se avisa que o numero voltou. Caido, ele nao consegue
// avisar: a falta do resumo das 21h e o sinal.
const s = String($('Ler mensagem').first().json.status || '').toUpperCase();
const dados = $getWorkflowStaticData('global');
const antes = dados.sessao || { status: 'WORKING', desde: '' };
const agoraISO = new Date().toISOString();
const voltou = s === 'WORKING' && antes.status && antes.status !== 'WORKING';
if (s && s !== antes.status) dados.sessao = { status: s, desde: agoraISO };
const dia = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' });
const hora = (iso) => (iso ? new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '?');
const texto = voltou ? '✅ O WhatsApp do RG voltou a funcionar. Estava ' + antes.status + ' desde ' + hora(antes.desde) + '.' : '';
return [{ json: { dia, tipo: 'sessao_' + (s || 'desconhecido').toLowerCase(), pessoa: '', avisar: voltou, texto } }];

// Why Code: mesma regra de telefoneWhatsApp em functions/whatsapp-cin.js (55 + DDD + nono digito).
// "conversa" e a chave das tabelas do Cidinho (falas, pausa): o telefone, ou o chat quando
// nao ha celular brasileiro (fixo com WhatsApp Business, numero estrangeiro, LID sem
// traducao). Antes essas pessoas caiam todas na mesma conversa (telefone vazio).
const m = $('Ler mensagem').first().json;
const lid = $input.first().json || {};
const origem = m.ehLid ? String(lid.pn || lid.phoneNumber || '') : m.chatId;
let d = origem.split('@')[0].replace(/\D/g, '');
if (d.length > 11 && d.startsWith('55')) d = d.slice(2);
if (d.length === 10 && /^[6-9]/.test(d.slice(2))) d = d.slice(0, 2) + '9' + d.slice(2);
const telefone = /^[1-9]{2}9\d{8}$/.test(d) ? '55' + d : '';
return [{ json: { ...m, telefone, conversa: telefone || ('chat_' + m.chatId), em: new Date().toISOString() } }];

const WAHA = "http://camara-itanhandu_waha-cin:3000";
// Why Code: separa texto, audio, figurinha e outra midia; marca o que o Cidinho nao ve
// ([foto], [vídeo], [documento], [mídia]) para tudo passar pela mesma rajada, teto e
// historico; acerta o link do audio e guarda a mensagem citada (contexto da IA).
// Constantes (montar-entrada.mjs): WAHA
const p = ($('Hash do segredo').first().json.body || {}).payload || {};
const msgid = String(p.id || '');
const legenda = String(p.body || '').trim().slice(0, 2000);
const media = p.media || {};
const mime = String(media.mimetype || '').toLowerCase();
const temMidia = p.hasMedia === true || Boolean(mime);
const audio = temMidia && mime.startsWith('audio/');
const figurinha = temMidia && mime === 'image/webp';
let marca = '[mídia]';
if (mime.startsWith('image/')) marca = '[foto]';
else if (mime.startsWith('video/')) marca = '[vídeo]';
else if (mime.startsWith('application/') || mime.startsWith('text/')) marca = '[documento]';
// O WAHA monta o link com o endereco dele mesmo (localhost). Troca SEMPRE pelo
// endereco interno: a chave do WAHA vai junto no pedido e so pode ir para ele.
const urlAudio = audio && media.url ? String(media.url).replace(/^https?:\/\/[^/]+/, WAHA) : '';
let tipo = 'texto';
let texto = legenda;
if (figurinha) tipo = 'figurinha';
else if (audio) {
  tipo = urlAudio ? 'audio' : 'texto';
  texto = urlAudio ? '' : '[áudio não entendido]';
} else if (temMidia) texto = (marca + ' ' + legenda).trim();
else if (!legenda) texto = '[mídia]';
const citado = String((p.replyTo && p.replyTo.body) || '').trim().slice(0, 300);
return [{ json: { tipo, msgid, texto, urlAudio, citado } }];

// Why Code: mesmo filtro do robo da Sucupira. O Whisper inventa frase em silencio ou
// ruido ("Thank you for watching", "Legendas pela comunidade"); ai a fala vira
// [áudio não entendido] e a resposta fixa pede para repetir.
const t = String(($input.first().json || {}).text || '').trim();
const c = t.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const palavras = c.split(/[^a-z0-9]+/).filter(Boolean);
const EN = new Set(['the', 'you', 'your', 'thank', 'thanks', 'watching', 'watch', 'much', 'same', 'this', 'that', 'with', 'what', 'are', 'is', 'it', 'and', 'of', 'for', 'my', 'subscribe', 'video', 'please']);
const PT = new Set(['de', 'que', 'o', 'a', 'os', 'as', 'do', 'da', 'dos', 'das', 'em', 'um', 'uma', 'para', 'pra', 'com', 'nao', 'eu', 'voce', 'vc', 'sim', 'quero', 'qual', 'quando', 'como', 'tem', 'no', 'na', 'se', 'mais', 'por', 'me', 'meu', 'minha', 'ta', 'e', 'esse', 'essa', 'isso', 'aqui', 'ai', 'la', 'bom', 'boa', 'dia', 'tarde', 'noite', 'oi', 'ola', 'obrigado', 'obrigada', 'rg', 'identidade', 'agendar', 'agendamento', 'vaga', 'certidao']);
const en = palavras.filter((w) => EN.has(w)).length;
const pt = palavras.filter((w) => PT.has(w)).length;
const alucinacao = /(thank you|thanks for watching|for watching|subscribe|subtitles?|legendas? (pela|por)|legendado|amara\.org|obrigad[oa] por assistir|inscreva-se)/.test(c) || (en >= 2 && pt === 0);
const audioOk = /[a-z]/.test(c) && !alucinacao;
return [{ json: { audioOk, texto: audioOk ? t.slice(0, 2000) : '[áudio não entendido]' } }];

// Why Code: junta o texto (digitado, transcrito ou a marca da midia) com o id da mensagem para a tabela.
const t = $('Tipo da mensagem').first().json;
const texto = $('Ler transcrição').isExecuted ? $('Ler transcrição').first().json.texto : t.texto;
return [{ json: {
  telefone: $('Telefone').first().json.conversa,
  papel: 'user',
  texto: String(texto || '').slice(0, 2000),
  quando: new Date().toISOString(),
  msgid: t.msgid || ('sem-id-' + Date.now()),
} }];

const TETO = 20;
const TEXTO_TETO = "Por hoje eu já respondi bastante por aqui. 🙏 Para continuar, fale com a recepção da Câmara pelo WhatsApp *(35) 3504-0397*.\n\nAgendar, consultar ou cancelar: https://cin.itanhandu.cam.mg.gov.br";
const MENU_APRESENTACAO = "Oi! Sou o *Cidinho*, do RG da Câmara de Itanhandu. 👋\nResponda com o número:\n\n1️⃣ Agendar / tem vaga?\n2️⃣ O que levar\n3️⃣ Consultar ou cancelar\n4️⃣ RG de criança\n5️⃣ Prazo e entrega\n6️⃣ Falar com uma pessoa\n\nOu escreva sua dúvida.";
const MENU_OPCOES = "Responda com o número:\n\n1️⃣ Agendar / tem vaga?\n2️⃣ O que levar\n3️⃣ Consultar ou cancelar\n4️⃣ RG de criança\n5️⃣ Prazo e entrega\n6️⃣ Falar com uma pessoa\n\nOu escreva sua dúvida.";
const OPCAO_1_PERGUNTA = "Quero agendar o RG. Tem vaga?";
const OPCOES_FIXAS = {"2":"📄 *O que levar:*\n• *Certidão* original, digital ou autenticada em cartório:\n   – solteiro: nascimento\n   – casado: casamento\n   – viúvo ou divorciado: casamento com averbação\n• Número do CPF\n• Comprovante de endereço\nXerox e foto da certidão de papel não valem.","3":"Para consultar ou cancelar por aqui, mande o *código do agendamento* (começa com CIN-). Ele está na mensagem de confirmação que enviamos neste WhatsApp.\nOu pelo site, com CPF, data de nascimento e código: https://cin.itanhandu.cam.mg.gov.br/cin/consultar-ou-cancelar/\nNão dá para trocar o dia: cancele e agende de novo na segunda, às 8h.","4":"A criança *precisa ir*, com pai, mãe ou responsável (com RG ou CNH).\nLeve a *certidão de nascimento* dela. Menor de 3 anos: 1 foto 3x4 de fundo branco.\nAvó, tio e outros: levem também o termo de guarda.","5":"A carteira chega *pelos Correios* em até 15 dias úteis.\nAcompanhe no *MG App*. Zona rural: busque na Câmara 15 dias depois.","6":"Pronto! ✅ Avisei a equipe da Câmara. O atendimento é de *terça a sexta, das 14h às 17h*: uma pessoa vai falar com você nesse horário.\nSe preferir, chame a recepção: *(35) 3504-0397*."};
const TEXTOS_OPCAO_6 = ["Pronto! ✅ Avisei a equipe da Câmara. O atendimento é de *terça a sexta, das 14h às 17h*: uma pessoa vai falar com você nesse horário.\nSe preferir, chame a recepção: *(35) 3504-0397*.","Pronto! ✅ Avisei a equipe da Câmara. Uma pessoa vai falar com você assim que possível.\nSe preferir, chame a recepção: *(35) 3504-0397*."];
const TEXTO_MIDIA = "Não consigo ver foto, vídeo nem documento. 🙏 Escreva sua dúvida em texto ou mande um áudio, por favor.\nSe preferir falar com uma pessoa, responda *6*.";
const TEXTO_AUDIO = "Não consegui entender o seu áudio. 🙏 Pode mandar de novo ou escrever a sua dúvida?";
const TEXTO_QUAL_CODIGO = "Achei mais de um agendamento neste WhatsApp. Mande o *código* (começa com CIN-) do que você quer consultar ou cancelar. Ele está em cada mensagem de confirmação.";
const BOTAO = "ola tenho uma duvida sobre o rg";
const CUMPRIMENTO = ["oi","oii","oiii","ola","opa","e","ai","eai","bom","boa","dia","tarde","noite","cidinho","menu","opcoes","opcao","inicio","ajuda","tudo","bem"];
// Why Code: decide se esta execucao responde (e a ultima mensagem da rajada?), aplica
// o teto e escolhe o caminho: silencio (so emoji), resposta fixa (menu, opcoes, midia),
// agendamento (codigo CIN-: consulta e cancelamento) ou IA, com a conversa e o contexto
// (ultimo aviso do WhatsApp e mensagem citada). Tambem decide os avisos ao responsavel.
// Constantes (montar-entrada.mjs): TETO, TEXTO_TETO, MENU_APRESENTACAO, MENU_OPCOES,
// OPCAO_1_PERGUNTA, OPCOES_FIXAS, TEXTOS_OPCAO_6, TEXTO_MIDIA, TEXTO_AUDIO,
// TEXTO_QUAL_CODIGO, BOTAO, CUMPRIMENTO
const minha = $('Fala da pessoa').first().json.msgid;
const agora = Date.now();
const limite = agora - 24 * 3600 * 1000;
const linhas = $('Conversa recente').all().map((i) => i.json)
  .filter((r) => r && r.telefone && r.papel && new Date(r.quando).getTime() >= limite);
const ordem = (a, b) => (new Date(a.quando) - new Date(b.quando)) || ((a.id || 0) - (b.id || 0));
const falas = linhas.filter((r) => r.papel === 'user' || r.papel === 'assistant').sort(ordem);
const alertasJa = new Set(linhas.filter((r) => r.papel === 'alerta').map((r) => String(r.texto || '')));
const daPessoa = falas.filter((r) => r.papel === 'user');
const ultima = daPessoa[daPessoa.length - 1];
// Chegou outra mensagem depois desta: quem responde e a execucao da mais nova.
if (!ultima || ultima.msgid !== minha) return [{ json: { minhaVez: false } }];

const respostas = falas.filter((r) => r.papel === 'assistant');
const ultimas = daPessoa.slice(-4, -1).map((f) => String(f.texto || '').slice(0, 200));
let fim = -1;
falas.forEach((f, i) => { if (f.papel === 'assistant') fim = i; });
const anteriores = falas.slice(0, fim + 1).slice(-12);
const rajada = falas.slice(fim + 1);
const primeira = respostas.length === 0;
const ultimaResposta = respostas[respostas.length - 1] || null;
const textos = rajada.map((f) => String(f.texto || '').trim());
const juntas = textos.join(' ');
const atual = juntas.slice(0, 300);
const normal = juntas.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const palavras = normal.split(/[^a-z0-9]+/).filter(Boolean);
const frase = palavras.join(' ');

const eventos = [];
const avisar = [];
const saida = (caminho, extra) => [{ json: { minhaVez: true, caminho, eventos, avisar, ultimas, atual, ...extra } }];
const fixa = (resposta, evento) => { if (evento) eventos.push(evento); return saida('fixa', { resposta }); };
const agendamento = (acao, protocolo) => {
  eventos.push(acao === 'cancelar' ? 'protocolo_cancelar' : 'protocolo_consulta');
  return saida('agendamento', { acao, protocolo });
};

if (respostas.length >= TETO) return fixa(TEXTO_TETO, 'teto');

// O que o WhatsApp guarda desta conversa: os avisos (a confirmacao traz o codigo CIN-).
const doWhats = $('Últimas do WhatsApp').isExecuted
  ? $('Últimas do WhatsApp').all().map((i) => i.json).filter((m) => m && m.timestamp)
  : [];
const AVISO = /(RG (está |foi )?agendado|Agendamento do RG confirmado|Agendamento confirmado|seu RG é hoje|Hoje é o seu RG|atendimento do RG é hoje|foi \*cancelado\*|\*cancelou\*|RG chegou|RG está pronto|identidade chegou|Como foi o seu atendimento)/i;
const avisos = doWhats
  .filter((m) => m.fromMe === true && m.source !== 'app' && AVISO.test(String(m.body || ''))
    && agora / 1000 - Number(m.timestamp) < 8 * 86400)
  .sort((a, b) => b.timestamp - a.timestamp);
const RE_COD = /\bcin[\s-]*([a-z0-9]{8})\b/i;
const codigoEm = (t) => { const m = RE_COD.exec(String(t || '')); return m ? 'CIN-' + m[1].toUpperCase() : ''; };
const codigosDosAvisos = [...new Set(avisos.map((a) => codigoEm(a.body)).filter(Boolean))];
const citado = String($('Tipo da mensagem').first().json.citado || '');

// Abertura das vagas (segunda, 8h-10h59): foto ou "nao consigo agendar" pode ser falha do site.
const sp = new Date(new Date(agora).toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const abertura = sp.getDay() === 1 && sp.getHours() >= 8 && sp.getHours() < 11;
const temFoto = /\[foto\]/i.test(juntas);
const problemaSite = /\b(nao|n)\s+(consigo|consegui|to conseguindo|estou conseguindo|da pra|deu pra)\s+(finalizar|concluir|terminar|confirmar|agendar|marcar|entrar)|\berro\b|\btravou\b|\btravando\b|nao carrega|site (caiu|fora do ar)/.test(normal);
if (abertura && (temFoto || problemaSite) && !alertasJa.has('site')) avisar.push('site');

// 1) So emoji ou pontuacao (❤️, 👍): nao responde.
if (textos.length && textos.every((t) => t && !/[\p{L}\p{N}]/u.test(t))) {
  eventos.push('silencio');
  return saida('silencio', {});
}

// 2) Confirmacao do cancelamento: a ultima resposta mostrou o codigo e pediu CANCELAR ha menos de 30 min.
const pediuCancelar = ultimaResposta && /responda \*CANCELAR\*/i.test(String(ultimaResposta.texto || ''))
  && agora - new Date(ultimaResposta.quando).getTime() < 30 * 60 * 1000;
const codPendente = pediuCancelar ? codigoEm(ultimaResposta.texto) : '';
if (codPendente && /^(sim|s|pode|pode sim|pode cancelar|sim pode cancelar|cancela|cancelar|cancelar sim|sim cancelar|quero cancelar|confirmo|confirmar|isso)$/.test(frase)) {
  return agendamento('cancelar', codPendente);
}

// 3) Codigo CIN- escrito: consulta (e a resposta pede CANCELAR para cancelar).
const codTexto = codigoEm(juntas);
if (codTexto) return agendamento('consultar', codTexto);

// 4) Quer cancelar ou saber do agendamento sem mandar o codigo: o da mensagem citada,
//    ou o da confirmacao recente (so se houver um). Sem codigo, a IA pede o codigo.
const querCancelar = /\b(cancel\w*|desmarc\w*|desagend\w*)\b|nao vou (poder )?(ir|comparecer)|nao (posso|consigo|vou conseguir) (ir|comparecer)/.test(normal);
const querConsultar = /\b(meu|minha) (agendamento|horario|hora|rg|vaga)\b|\bque (dia|hora|horas) (e|fica|ficou) (o )?meu\b|\bconsult\w*\b|\b(estou|to|fui|ta|esta) agendad/.test(normal);
const opcaoTres = /^\s*3\s*(️)?\s*(⃣)?\s*[.)]?\s*$/.test(juntas);
if (querCancelar || querConsultar || opcaoTres) {
  const codCitado = codigoEm(citado);
  if (codCitado) return agendamento('consultar', codCitado);
  if (codigosDosAvisos.length === 1) return agendamento('consultar', codigosDosAvisos[0]);
  if (codigosDosAvisos.length > 1) return fixa(TEXTO_QUAL_CODIGO, 'protocolo_varios');
  if (opcaoTres) return fixa(OPCOES_FIXAS[3], 'opcao_3');
}

// 5) So midia, ou audio que nao deu para entender.
const MARCA = /^\[(foto|vídeo|video|documento|mídia|midia|áudio não entendido|audio nao entendido)\]$/i;
if (textos.length && textos.every((t) => MARCA.test(t))) {
  return fixa(textos.some((t) => /udio/i.test(t)) ? TEXTO_AUDIO : TEXTO_MIDIA, 'midia');
}

// 6) Menu: so cumprimento (ou MENU) ou o texto pronto do botao do site; um numero de 1 a 6 escolhe.
const CUMPRIMENTOS = new Set(CUMPRIMENTO);
const doBotao = (' ' + frase + ' ').includes(' ' + BOTAO + ' ');
const resto = doBotao ? (' ' + frase + ' ').split(' ' + BOTAO + ' ').join(' ').split(' ').filter(Boolean) : palavras;
const soNumero = /^\s*([1-6])\s*(️)?\s*(⃣)?\s*[.)]?\s*$/.exec(juntas);
let opcao = soNumero ? Number(soNumero[1]) : 0;
const PEDE_PESSOA = /^(quero |queria |preciso |gostaria de )?(falar com |conversar com )?(um |uma |o |a )?(atendente|atendimento|atendimento humano|humano|pessoa|pessoa de verdade|alguem|funcionario)( por favor| pfv| pf)?$/;
if (!opcao && PEDE_PESSOA.test(frase)) opcao = 6;
const ehMenu = !opcao && !juntas.includes('?') && palavras.length > 0 && (doBotao || juntas.length <= 40)
  && resto.every((w) => CUMPRIMENTOS.has(w));
if (ehMenu) return fixa(primeira ? MENU_APRESENTACAO : MENU_OPCOES, 'menu');
if (opcao >= 2) {
  // Opcao 6 avisa o responsavel uma vez por conversa de 24 h.
  if (opcao === 6 && !alertasJa.has('atendimento') && !respostas.some((f) => TEXTOS_OPCAO_6.includes(f.texto))) {
    avisar.push('atendimento');
  }
  return fixa(OPCOES_FIXAS[opcao], 'opcao_' + opcao);
}

// 7) IA, com o contexto do WhatsApp (sem codigo nem nome).
const mensagens = [];
for (const f of [...anteriores, ...rajada]) {
  const ult = mensagens[mensagens.length - 1];
  if (ult && ult.role === f.papel) ult.content += '\n' + f.texto;
  else mensagens.push({ role: f.papel, content: String(f.texto || '') });
}
while (mensagens.length && mensagens[0].role !== 'user') mensagens.shift();
if (opcao === 1 && mensagens.length) mensagens[mensagens.length - 1].content = OPCAO_1_PERGUNTA;
const limpar = (t) => String(t || '').replace(/\*/g, '').replace(/\bcin[\s-]*[a-z0-9]{8}\b/gi, 'CIN-…')
  .replace(/^([^\p{L}]*)\p{Lu}\p{Ll}+, /u, '$1').replace(/\s+/g, ' ').trim();
const hora = (ts) => new Date(Number(ts) * 1000).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const contexto = [];
if (avisos[0]) contexto.push('Último aviso que este número mandou à pessoa (' + hora(avisos[0].timestamp) + '): «' + limpar(String(avisos[0].body || '').split('\n')[0]).slice(0, 160) + '».');
if (citado) contexto.push('A pessoa está respondendo a esta mensagem: «' + limpar(citado).slice(0, 200) + '».');
eventos.push(opcao === 1 ? 'opcao_1' : 'ia');
return saida('ia', { mensagens, primeira, contexto: contexto.join('\n') });

const SITE = "https://cin.itanhandu.cam.mg.gov.br";
const LINK_CONSULTAR = "https://cin.itanhandu.cam.mg.gov.br/cin/consultar-ou-cancelar/";
const TELEFONE_RECEPCAO = "(35) 3504-0397";
// Why Code: transforma a resposta da function cinRoboAgendamento (consulta ou
// cancelamento pelo codigo CIN-) no texto curto do WhatsApp. O codigo vai na resposta
// da consulta: e dele que sai o CANCELAR seguinte (preparar-cidinho.js, passo 2).
// Constantes (montar-entrada.mjs): SITE, LINK_CONSULTAR, TELEFONE_RECEPCAO
const p = $('Preparar Cidinho').first().json;
const r = $input.first().json || {};
const cod = p.protocolo;
const quando = r.quando ? '*' + r.quando + '*' : 'desse agendamento';
const semResposta = r.error || typeof r.ok !== 'boolean' || (r.ok === false && r.motivo === 'erro');
let resposta;
let evento;
if (semResposta) {
  evento = 'falha_agendamento';
  resposta = 'Não consegui consultar agora. 🙏 Tente de novo daqui a pouco ou use o site (CPF, data de nascimento e código): ' + LINK_CONSULTAR + '\nSe preferir, responda *6* para falar com uma pessoa.';
} else if (r.ok === false && r.motivo === 'nao_encontrado') {
  evento = 'protocolo_nao_encontrado';
  resposta = 'Não achei o agendamento ' + cod + ' ligado a este WhatsApp. Confira o código na mensagem de confirmação, ou consulte pelo site (CPF, data de nascimento e código): ' + LINK_CONSULTAR + '\nSe precisar, responda *6*.';
} else if (p.acao === 'cancelar' && r.ok === true && r.cancelado === true) {
  evento = 'cancelamento';
  resposta = 'Pronto! ✅ Seu RG de ' + quando + ' foi *cancelado* e a vaga foi liberada.\nNovas vagas toda segunda, às 8h: ' + SITE;
} else {
  evento = p.acao === 'cancelar' ? 'cancelamento_recusado' : 'consulta';
  switch (r.situacao) {
    case 'agendado':
      resposta = 'Seu RG (' + cod + ') está marcado para ' + quando + ', na Câmara.\nLeve a certidão (original, digital ou autenticada), o CPF e o comprovante de endereço.\nPara cancelar e liberar a vaga, responda *CANCELAR*.';
      break;
    case 'passou':
      resposta = 'O horário desse agendamento (' + (r.quando || cod) + ') já passou. Se precisar de ajuda, responda *6*.';
      break;
    case 'atendido':
      resposta = 'Esse atendimento (' + (r.quando || cod) + ') já foi feito. A carteira chega pelos Correios em até 15 dias úteis; acompanhe no MG App.';
      break;
    case 'faltou':
      resposta = 'Consta falta nesse agendamento (' + (r.quando || cod) + '). Para orientação, fale com a recepção: ' + TELEFONE_RECEPCAO + ', ou responda *6*.';
      break;
    case 'cancelado':
      resposta = 'Esse agendamento (' + (r.quando || cod) + ') está *cancelado*. Novas vagas toda segunda, às 8h: ' + SITE;
      break;
    default:
      resposta = 'Não consegui ver a situação desse agendamento. Consulte pelo site: ' + LINK_CONSULTAR + ', ou responda *6*.';
  }
}
return [{ json: { resposta, evento } }];

